// Meta manda GET ?hub.mode=subscribe&hub.verify_token=...&hub.challenge=...
// Si el token coincide con nuestro secreto, hay que devolver el challenge tal cual.
const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WEBHOOK_VERIFY_TOKEN;
return [{ json: { body: ok ? q['hub.challenge'] : 'token invalido', statusCode: ok ? 200 : 403 } }];

// El payload de Meta viene anidado: entry[].changes[].value.messages[]
// Los avisos de estado (sent/delivered/read) NO traen messages -> no se emite nada y el flujo muere aqui.
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const e of (body.entry || [])) {
    for (const ch of (e.changes || [])) {
      const v = ch.value || {};
      const contacto = (v.contacts && v.contacts[0]) || {};
      for (const m of (v.messages || [])) {
        out.push({ json: {
          wa_id: m.from,
          nombre: (contacto.profile && contacto.profile.name) || '',
          tipo: m.type,
          texto: (m.text && m.text.body) || '',
          message_id: m.id,
          timestamp: m.timestamp
        }});
      }
    }
  }
}
return out;
